Else { Set tValue = "", tLen = 0}
If 6 > tLen {
	Set tPadding = $get(pPadArray(6 - tLen))
	If tPadding = "" {
		Set $piece(tPadding, $char(32), (6 - tLen + 1)) = ""
		Set pPadArray(6-tLen) = tPadding
	}
